/** @brief TIER-TOL band for `standardNormal<double>` (absolute AND relative).
 *         aether's Box-Muller routes `sqrt`/`log`/`sincos` through
 *         `aether::math`, so it is not bit-reproducible across the
 *         host/device transcendental implementations the way the integer and
 *         uniform streams are. */
inline constexpr double kNormalDoubleTol = 1.0e-12;
/** @brief TIER-TOL band for `standardNormal<float>` — looser, because the
 *         device FP32 route reaches `sincosf` where cuRAND reaches the fast
 *         `__sincosf` approximation. */
inline constexpr float kNormalFloatTol = 1.0e-5f;

